"use strict";
/** Incremental, verified and privacy-bounded project memory learning at Gate C.
 * Jev only decides if an abstract topic is worth preserving. Source paths,
 * memory bodies and code never leave the machine. Facts are extracted locally
 * from Gate V's fresh file snapshot, never generated by Jev.
 */
const fs=require("node:fs");
const path=require("node:path");
const crypto=require("node:crypto");
const {systemOne,jevConfig}=require("./jev");
const {readProjectEnv}=require("./project-env");
const SKIP=new Set(["client","server","src","scripts","common","shared","system","ui","modules","main","core"]);
function slug(value){return String(value||"").toLowerCase().replace(/[^a-z0-9_-]/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"").slice(0,60);}
function topicFor(files){
  const names=files.map(f=>{
    const parts=f.replace(/\\/g,"/").split("/");
    const marker=parts.findIndex(v=>v==="resources");
    if(marker>=0&&parts[marker+2])return slug(parts[marker+2]);
    return slug(parts.length>1?parts[0]:path.parse(f).name);
  }).filter(n=>n&&!SKIP.has(n));
  if(!names.length)return null;
  const frequency=new Map();
  for(const name of names)frequency.set(name,(frequency.get(name)||0)+1);
  return [...frequency].sort((a,b)=>b[1]-a[1])[0][0];
}
function memoryState(root){return path.join(root,".fxmind","state","auto-memory.json");}
function readState(root){try{return JSON.parse(fs.readFileSync(memoryState(root),"utf8"));}catch{return {seen:{}};}}
function persist(root,state){const file=memoryState(root);fs.mkdirSync(path.dirname(file),{recursive:true});const temp=file+"."+process.pid+".tmp";try{fs.writeFileSync(temp,JSON.stringify(state,null,2));fs.renameSync(temp,file);}finally{try{fs.unlinkSync(temp);}catch{}}}
function reviewIsVerified(session){
 if(session?.gates?.C?.complete!==true)return false;
 const gate=session?.gates?.V;
 return gate?.complete===true && gate?.snapshot && Object.keys(gate.snapshot).length &&
   gate.evidence?.independentReview?.verdict==="verified" &&
   Array.isArray(gate.evidence.checks) && gate.evidence.checks.length>0 &&
   gate.evidence.checks.every(c=>c.status==="passed");
}
function verifiedFiles(root,session){
 const snapshot=session.gates.V.snapshot;
 const files=Object.keys(snapshot);
 if(files.length>12)return [];
 return files.filter(f=>{
  if(!/^resources\//.test(f)||f.includes("..")||!/[.]((lua)|(js)|(ts)|(tsx)|(json)|(html)|(css))$/.test(f))return false;
  const full=path.resolve(root,f);
  if(!full.startsWith(path.resolve(root)+path.sep))return false;
  try{
   const st=fs.statSync(full);
   return st.isFile()&&st.size<=1024*1024&&crypto.createHash("sha256").update(fs.readFileSync(full)).digest("hex")===snapshot[f];
  }catch{return false;}
 });
}
function symbolsFromFiles(root,files){
 const symbols=new Set();
 for(const file of files.slice(0,8)){
  const body=fs.readFileSync(path.join(root,file),"utf8");
  const re=/(?:RegisterNetEvent|AddEventHandler|RegisterCommand|Trigger(?:Server|Client)Event)\s*\(\s*["']([a-zA-Z_][\w:.-]{3,75})["']|(?:function\s+|local\s+function\s+)([a-zA-Z_][\w.:]{3,75})/g;
  let match;
  while((match=re.exec(body))&&symbols.size<12)symbols.add(match[1]||match[2]);
 }
 return [...symbols];
}
const QUESTION={type:"choice",instructions:"Decide whether a verified software change should add durable project memory. Prefer save for reusable mechanics/cross-file patterns and skip for routine, trivial or transient changes. Use only the resource label and deterministic counts, not any imagined implementation details.",criteria:{save:"Reusable project behavior or multiple-file verified pattern.",skip:"Routine, one-off or insufficient reusable knowledge."}};
async function learnAfterGate(root,session,options={}){
 if(!reviewIsVerified(session))return {status:"skipped",reason:"no_verified_gate_v"};
 const files=verifiedFiles(root,session);
 if(!files.length)return {status:"skipped",reason:"stale_or_unsupported_files"};
 const topic=topicFor(files);
 if(!topic)return {status:"skipped",reason:"no_topic"};
 const hash=crypto.createHash("sha256").update(JSON.stringify([topic,session.gates.V.snapshot])).digest("hex").slice(0,20);
 const state=readState(root);
 if(state.seen?.[hash])return {status:"skipped",reason:"duplicate",topic};
 const config=options.config||jevConfig(options.env,options.packageRoot);
 if(!config.enabled||!config.memoryEnabled||!config.apiKey)return {status:"skipped",reason:"jev_unavailable",topic};
 const result=await systemOne({resource:topic,fileCount:files.length,taskKind:String(session.kind||"unknown").slice(0,30)}, {preserve:QUESTION},{...options,config});
 const decision=result?.preserve;
 // Learning is only a relevance filter: all recorded facts still come from
 // independently verified local files. Keep its threshold independent from
 // stricter tool routing and task classification.
 const values=readProjectEnv(options.packageRoot||path.resolve(__dirname,"../.."),options.env||process.env);
 const configuredThreshold=Number(values.FXMIND_JEV_LEARN_MIN_CONFIDENCE);
 const threshold=Number.isFinite(configuredThreshold)&&configuredThreshold>=0.65&&configuredThreshold<=1
   ?configuredThreshold:0.70;
 if(decision?.choice!=="save"||!(Number(decision.confidence)>=threshold)){
   return {status:"skipped",reason:"jev_low_value_or_unavailable",topic};
 }
 const dir=path.join(root,".fxmind","memory");
 const target=path.join(dir,topic+".md");
 const names=symbolsFromFiles(root,files);
 const record=[
   "","## Verified source snapshot "+hash,
   "- Source: completed Gate V/C, independent reviewer verified, local sha256 rechecked",
   ...files.map(f=>"- File: `"+f+"`"),
   ...(names.length?["- Source symbols/events: "+names.map(n=>"`"+n+"`").join(", ")]:[]),
   "- Recheck current source before implementing; this record is not an API contract.",
   ""
 ].join("\n");
 const existed=fs.existsSync(target);
 const original=existed?fs.readFileSync(target,"utf8"):"";
 if(original.includes("Verified source snapshot "+hash))return {status:"skipped",reason:"already_recorded",topic};
 // Keep memories compact: after several distinct verified snapshots, prefer
 // a human/agent learn-mode consolidation over unbounded automatic append.
 if((original.match(/^## Verified source snapshot /gm)||[]).length>=8){
   return {status:"skipped",reason:"needs_compaction",topic};
 }
 if(!existed){
   fs.mkdirSync(dir,{recursive:true});
   const header=["---","topic: "+topic,"updated: "+new Date().toISOString().slice(0,10),"lang: en-compact","confidence: extracted","paths:",...files.map(f=>"  - "+f),"triggers: ["+topic+"]","symbols: ["+names.slice(0,8).join(", ")+"]","---","","# "+topic,"","Files:",...files.map(f=>"- `"+f+"`"),"","Pitfalls:","- Source structure must be reconfirmed before modification.",""].join("\n");
   fs.writeFileSync(target,header+record);
 }else{
   // Never rewrite a hand-written topic: add a bounded, provenance-backed delta.
   fs.appendFileSync(target,record);
 }
 state.seen={...(state.seen||{}),[hash]:{topic,at:Date.now()}};
 persist(root,state);
 return {status:"learned",topic,created:!existed,files:files.length,symbols:names.length};
}
module.exports={learnAfterGate,topicFor,reviewIsVerified,verifiedFiles,symbolsFromFiles};
